          />

          {/* Slide Over Panel */}
          <motion.div
            initial={{ x: isRtl ? "-100%" : "100%" }}
            animate={{ x: 0 }}
            exit={{ x: isRtl ? "-100%" : "100%" }}
            transition={{ type: "spring", bounce: 0, duration: 0.4 }}
            className={`absolute ${isRtl ? "left-0 border-r" : "right-0 border-l"} top-0 bottom-0 w-full md:w-[600px] lg:w-[800px] bg-white dark:bg-slate-900 dark:border-slate-800 shadow-2xl flex flex-col`}
            dir={isRtl ? "rtl" : "ltr"}
          >
            {/* Header */}
            <div className="flex items-center justify-between p-6 border-b dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900">
              <div>
                <h2 className="text-xl font-bold text-slate-900 dark:text-white">
                  {title}
                </h2>
                {subtitle && (
                  <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
                    {subtitle}
                  </p>
                )}
              </div>
              <div className="flex items-center gap-2">
                <Button variant="secondary" className="gap-2" onClick={() => exportToCSV(records, title)}>
                  <Download className="w-4 h-4" />
                  {isRtl ? "export" : "Export"}
                </Button>
                <button
                  onClick={onClose}
                  className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>

            {/* Content Table */}
            <div className="flex-1 overflow-auto p-6 relative">
              {isLoading ? (
                <div className="absolute inset-0 flex items-center justify-center bg-white/50 dark:bg-slate-900/50">
                  <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
                </div>
              ) : records.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-slate-500">
                  <p>{isRtl ? "No data available." : "No data available."}</p>
                </div>
              ) : (
                <div className="border dark:border-slate-800 rounded-lg overflow-hidden">
                  <table className="w-full text-sm text-left">
                    <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-600 dark:text-slate-300 font-medium border-b dark:border-slate-800">
                      <tr>
                        {Object.keys(visibleRecords[0] || {}).map((key) => (
                          <th key={key} className="px-4 py-3 whitespace-nowrap">
                            {key.replace(/_/g, " ").replace(/\b\w/g, l => l.toUpperCase())}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y dark:divide-slate-800 bg-white dark:bg-slate-900">
                      {visibleRecords.map((row, i) => (
                        <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                          {Object.values(row).map((val: any, j) => (
                            <td key={j} className="px-4 py-3 text-slate-700 dark:text-slate-300 max-w-[200px] truncate">
                              {typeof val === 'object' ? JSON.stringify(val) : String(val)}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>

            {/* Pagination Footer */}
            {!isLoading && records.length > 0 && (
              <div className="p-4 border-t dark:border-slate-800 bg-slate-50 dark:bg-slate-900 flex items-center justify-between">
                <p className="text-sm text-slate-500">
                  {isRtl ? "an offer" : "Showing"} {((page - 1) * itemsPerPage) + 1} {isRtl ? "to" : "to"} {Math.min(page * itemsPerPage, records.length)} {isRtl ? "from" : "of"} {records.length} {isRtl ? "register" : "records"}
                </p>
                <div className="flex items-center gap-2">
                  <Button 
                    variant="secondary" 
                    disabled={page === 1}
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                  >
                    <ChevronLeft className={`w-4 h-4 ${isRtl ? "rotate-180" : ""}`} />
                  </Button>
                  <Button 
                    variant="secondary" 
                    disabled={page === totalPages}
                    onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  >
                    <ChevronRight className={`w-4 h-4 ${isRtl ? "rotate-180" : ""}`} />
                  </Button>
                </div>
              </div>
            )}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { useI18n } from "@/i18n/I18nContext";
import { Filter, Search } from "lucide-react";
import type { CrmDashboard } from "../models/dashboard-types";
import { useDashboardStore } from "../models/useDashboardStore";

interface DashboardFiltersProps {
  dashboard: CrmDashboard;
}

export function DashboardFilters({ dashboard }: DashboardFiltersProps) {
  const { lang } = useI18n();
  const isRtl = lang === "ar";
  const { filters, setFilters } = useDashboardStore();

  // If no default filters are defined, we don't show the filter bar.
  if (!dashboard.defaultFilters || Object.keys(dashboard.defaultFilters).length === 0) {
    return null;
  }

  return (
    <div className={`w-full p-4 border-b dark:border-gray-800 bg-gray-50/50 dark:bg-gray-900/50 flex flex-wrap items-center gap-4 ${isRtl ? "rtl" : "ltr"}`} dir={isRtl ? "rtl" : "ltr"}>
      <div className="flex items-center gap-2 text-sm font-medium text-gray-500">
        <Filter className="w-4 h-4" />
        {isRtl ? "Categories:" : "Filters:"}
      </div>

      {Object.entries(dashboard.defaultFilters).map(([key, filterSpec]: [string, any]) => (
        <div key={key} className="flex items-center gap-2 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-lg px-3 py-1.5 shadow-sm">
          <span className="text-xs text-gray-500 font-medium">
            {filterSpec.label || key}:
          </span>
          {filterSpec.type === "SELECT" ? (
            <select 
              className="text-sm border-none bg-transparent focus:ring-0 cursor-pointer p-0 font-medium text-gray-900 dark:text-gray-100"
              value={filters[key] || ""}
              onChange={(e) => setFilters({ ...filters, [key]: e.target.value })}
            >
              <option value="">{isRtl ? "everyone" : "All"}</option>
              {filterSpec.options?.map((opt: any) => (
                <option key={opt.value} value={opt.value}>{opt.label}</option>
              ))}
            </select>
          ) : filterSpec.type === "SEARCH" ? (
            <div className="flex items-center gap-1">
              <Search className="w-3 h-3 text-gray-400" />
              <input 
                type="text" 
                className="text-sm border-none bg-transparent focus:ring-0 p-0 w-24 placeholder-gray-400 font-medium text-gray-900 dark:text-gray-100"
                placeholder={isRtl ? "research..." : "Search..."}
                value={filters[key] || ""}
                onChange={(e) => setFilters({ ...filters, [key]: e.target.value })}
              />
            </div>
          ) : null}
        </div>
      ))}
      
      {Object.keys(filters).length > 0 && (
        <button 
          onClick={() => setFilters({})}
          className="text-xs text-blue-600 dark:text-blue-400 hover:underline font-medium"
        >
          {isRtl ? "Clear classifications" : "Clear filters"}
        </button>
      )}
    </div>
  );
}

"use client";

import { useMemo, useState, useRef, useEffect } from "react";
// @ts-ignore
import { ResponsiveGridLayout } from "react-grid-layout";
import "react-grid-layout/css/styles.css";
import "react-resizable/css/styles.css";

import { useDashboardStore } from "../models/useDashboardStore";
import { DashboardWidgetRenderer } from "./dashboard-widget-renderer";
import { DASHBOARD_COLUMN_COUNT } from "../models/dashboard-model";
import type { DashboardRunResult, CrmDashboardWidget } from "../models/dashboard-types";
import type { DashboardPointSelection } from "./renderers/dashboard-echarts-options";

const ResponsiveGrid = ResponsiveGridLayout as any;

interface DashboardGridProps {
  runResult?: DashboardRunResult;
  loading?: boolean;
  onPointSelect?: (widget: CrmDashboardWidget, selection: DashboardPointSelection) => void;
}

export function DashboardGrid({ runResult, loading, onPointSelect }: DashboardGridProps) {
  const { editMode, draftPlacements, updatePlacement } = useDashboardStore();

  const layout = useMemo(() => {
    return draftPlacements.map((p) => ({
      i: p.widgetId,
      x: p.x,
      y: p.y,
      w: p.width,
      h: p.height,
      minW: 2,
      minH: 2,
    }));
  }, [draftPlacements]);

  const handleLayoutChange = (currentLayout: any) => {
    if (!editMode || !Array.isArray(currentLayout)) return;
    currentLayout.forEach((item: any) => {
      updatePlacement(item.i, item.x, item.y, item.w, item.h);
    });
  };

  const [containerWidth, setContainerWidth] = useState<number>(1200);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    setContainerWidth(el.clientWidth);
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        if (entry.contentRect.width > 0) {
          setContainerWidth(entry.contentRect.width);
        }
      }
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={containerRef} className="w-full h-full min-h-[500px] p-2 sm:p-4 bg-slate-100/60 dark:bg-slate-950/40 rounded-2xl border border-slate-200/50 dark:border-slate-800/50">
      <ResponsiveGrid
        width={containerWidth}
        className={`layout ${editMode ? "dashboard-edit-mode" : ""}`}
        layouts={{ lg: layout }}
        breakpoints={{ lg: 1200, md: 996, sm: 768, xs: 480, xxs: 0 }}
        cols={{ lg: DASHBOARD_COLUMN_COUNT, md: 10, sm: 6, xs: 4, xxs: 2 }}
        rowHeight={65}
        margin={[16, 16]}
        onLayoutChange={handleLayoutChange}
        isDraggable={editMode}
        isResizable={editMode}
        useCSSTransforms={true}
        compactType="vertical"
      >
        {draftPlacements.map((placement) => {
          const widget = placement.widget;
          const result = runResult?.widgets?.[widget.id];

          return (
            <div
              key={placement.widgetId}
              className={`w-full h-full relative ${
                editMode ? "cursor-move ring-2 ring-blue-500/40 rounded-xl" : ""
              }`}
            >
              {editMode && (
                <div className="absolute inset-x-0 top-0 h-4 bg-blue-500/10 dark:bg-blue-400/10 z-20 flex items-center justify-center cursor-move rounded-t-xl">
                  <div className="w-10 h-1 bg-blue-500 dark:bg-blue-400 rounded-full" />
                </div>
              )}

              <DashboardWidgetRenderer
                widget={widget}
                result={result}
                loading={loading}
                onPointSelect={(sel) => onPointSelect?.(widget, sel)}
              />
            </div>
          );
        })}
      </ResponsiveGrid>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import type { CrmDashboardWidget, DashboardWidgetResult, DashboardVisualizationType } from "../models/dashboard-types";
import type { DashboardPointSelection } from "./renderers/dashboard-echarts-options";
import { WidgetSkeleton } from "./WidgetSkeleton";
import { WidgetEmpty } from "./WidgetEmpty";
import {
  BarChart3,
  LineChart,
  PieChart,
  Table as TableIcon,
  Trophy,
  Activity,
  Target,
  Gauge,
  TrendingUp,
  SlidersHorizontal,
  Layers,
} from "lucide-react";

// Renderers
import { DashboardECharts } from "./renderers/dashboard-echarts-adapter";
import { buildEchartsOption } from "./renderers/dashboard-echarts-options";
import { MetricCardRenderer } from "./renderers/MetricCardRenderer";
import { ProgressCardRenderer } from "./renderers/ProgressCardRenderer";
import { TableRenderer } from "./renderers/TableRenderer";
import { LeaderboardRenderer } from "./renderers/LeaderboardRenderer";

interface DashboardWidgetRendererProps {
  widget: CrmDashboardWidget;
  result?: DashboardWidgetResult;
  loading?: boolean;
  onPointSelect?: (selection: DashboardPointSelection) => void;
  className?: string;
}

function getWidgetIcon(type: DashboardVisualizationType) {
  switch (type) {
    case "METRIC_CARD":
      return TrendingUp;
    case "PROGRESS_CARD":
      return Target;
    case "TABLE":
      return TableIcon;
    case "LEADERBOARD":
      return Trophy;
    case "LINE":
    case "AREA":
    case "LINE_AREA":
      return LineChart;
    case "COLUMN":
    case "BAR":
    case "STACKED_BAR":
    case "STACKED_BAR_100":
    case "COMBO":
      return BarChart3;
    case "PIE":
    case "DONUT":
      return PieChart;
    case "SCATTER":
    case "BUBBLE":
    case "HEATMAP":
      return Activity;
    case "FUNNEL":
      return SlidersHorizontal;
    case "SEMI_CIRCLE_GAUGE":
    case "THREE_QUARTER_GAUGE":
    case "CIRCULAR_PROGRESS_GAUGE":
    case "DETAILED_SPEEDOMETER":
      return Gauge;
    default:
      return Layers;
  }
}

export function DashboardWidgetRenderer({
  widget,
  result,
  loading,
  onPointSelect,
  className = "",
}: DashboardWidgetRendererProps) {
  const type = widget.visualizationType;
  const Icon = getWidgetIcon(type);

  const content = useMemo(() => {
    if (loading || !result) {
      return <WidgetSkeleton type={type} />;
    }

    if (result.error) {
      return <WidgetEmpty message={result.error.message} />;
    }

    const isEchartsEmpty =
      type !== "METRIC_CARD" &&
      type !== "PROGRESS_CARD" &&
      type !== "TABLE" &&
      type !== "LEADERBOARD" &&
      (!result.series ||
        result.series.length === 0 ||
        result.series.every((s) => !s.points || s.points.length === 0));

    if (isEchartsEmpty) {
      return <WidgetEmpty />;
    }

    switch (type) {
      case "METRIC_CARD":
        return <MetricCardRenderer widget={widget} result={result} />;

      case "PROGRESS_CARD":
        return <ProgressCardRenderer widget={widget} result={result} />;

      case "TABLE":
        return <TableRenderer widget={widget} result={result} />;

      case "LEADERBOARD":
        return <LeaderboardRenderer widget={widget} result={result} />;

      case "LINE":
      case "AREA":
      case "LINE_AREA":
      case "COLUMN":
      case "BAR":
      case "STACKED_BAR":
      case "STACKED_BAR_100":
      case "COMBO":
      case "PIE":
      case "DONUT":
      case "SCATTER":
      case "BUBBLE":
      case "FUNNEL":
      case "HEATMAP":
      case "SEMI_CIRCLE_GAUGE":
      case "THREE_QUARTER_GAUGE":
      case "CIRCULAR_PROGRESS_GAUGE":
      case "DETAILED_SPEEDOMETER": {
        const option = buildEchartsOption(widget, result);
        if (!option) return <WidgetEmpty />;
        return (
          <DashboardECharts
            option={option}
            ariaLabel={widget.name}
            summary={[]}
            onPointSelect={onPointSelect}
          />
        );
      }

      default:
        return <WidgetEmpty message={`Unsupported visualization: ${type}`} />;
    }
  }, [type, widget, result, loading, onPointSelect]);

  return (
    <div
      className={`group w-full h-full bg-white/70 dark:bg-slate-900/50 backdrop-blur-xl border border-slate-200/50 dark:border-slate-800/50 rounded-2xl shadow-sm hover:shadow-xl hover:border-slate-300 dark:hover:border-slate-700/80 hover:-translate-y-0.5 transition-all duration-300 overflow-hidden flex flex-col ${className}`}
    >
      {/* Standardized Card Header */}
      <div className="h-[42px] px-4 border-b border-slate-200/50 dark:border-slate-800/40 bg-slate-50/40 dark:bg-slate-900/40 flex items-center justify-between flex-shrink-0 select-none transition-colors group-hover:bg-slate-50/80 dark:group-hover:bg-slate-900/60">
        <div className="flex items-center gap-2.5 min-w-0">
          <span className="p-1.5 rounded-lg bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/40 dark:to-indigo-900/20 text-blue-600 dark:text-blue-400 flex-shrink-0 shadow-sm border border-blue-100/50 dark:border-blue-800/30">
            <Icon className="w-3.5 h-3.5" />
          </span>
          <h3
            className="text-[13px] sm:text-sm font-semibold bg-gradient-to-r from-slate-800 to-slate-600 dark:from-slate-100 dark:to-slate-300 text-transparent bg-clip-text truncate"
            title={widget.name}
            style={{ fontFamily: "Outfit, Inter, sans-serif" }}
          >
            {widget.name}
          </h3>
        </div>
        <div className="flex items-center gap-1.5 flex-shrink-0 ms-3 opacity-70 group-hover:opacity-100 transition-opacity">
          <span className="text-[9px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest px-2 py-0.5 rounded-md bg-slate-100/80 dark:bg-slate-800/80 border border-slate-200/50 dark:border-slate-700/50 backdrop-blur-sm">
            {type.replace(/_/g, " ")}
          </span>
        </div>
      </div>

      {/* Card Content Body */}
      <div className="flex-1 min-h-0 w-full relative p-2 overflow-hidden">
        {content}
      </div>
    </div>
  );
}

"use client";

import { useI18n } from "@/i18n/I18nContext";
import type { DashboardWidgetResult, CrmDashboardWidget } from "../../models/dashboard-types";
import { formatDashboardValue } from "../../models/dashboard-utils";
import { exportToCSV } from "../../utils/export-utils";
import { Download } from "lucide-react";

interface TableRendererProps {
  widget: CrmDashboardWidget;
  result: DashboardWidgetResult;
}

function getStatusBadge(status?: string, severity?: string) {
  const val = (status || severity || "").toUpperCase();
  if (val === "WON" || val === "SUCCESS") {
    return "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border-emerald-500/20 shadow-[0_0_10px_rgba(16,185,129,0.1)]";
  }
  if (val === "NEGOTIATION" || val === "WARNING" || val === "AT_RISK") {
    return "bg-amber-500/10 text-amber-700 dark:text-amber-300 border-amber-500/20 shadow-[0_0_10px_rgba(245,158,11,0.1)]";
  }
  if (val === "CRITICAL" || val === "OFF_TRACK") {
    return "bg-rose-500/10 text-rose-700 dark:text-rose-300 border-rose-500/20 shadow-[0_0_10px_rgba(244,63,94,0.1)]";
  }
  return "bg-slate-500/10 text-slate-700 dark:text-slate-300 border-slate-500/20 shadow-[0_0_10px_rgba(148,163,184,0.1)]";
}

export function TableRenderer({ widget, result }: TableRendererProps) {
  const { lang } = useI18n();
  const isRtl = lang === "ar";

  if (result.result?.shape !== "ROWS") {
    return <div className="p-4 text-xs text-slate-400">Table data not available</div>;
  }

  const rows = result.result.rows;

  const handleExport = () => {
    exportToCSV(rows, widget.name || "Table Data");
  };

  return (
    <div className="flex flex-col w-full h-full overflow-hidden text-xs">
      <div className="flex justify-end px-3 py-1.5 bg-slate-50/80 dark:bg-slate-900/80 border-b border-slate-100 dark:border-slate-800">
        <button
          onClick={handleExport}
          className="flex items-center gap-1.5 text-xs font-semibold text-blue-600 dark:text-blue-400 hover:underline"
        >
          <Download className="w-3.5 h-3.5" />
          {isRtl ? "CSV export" : "Export CSV"}
        </button>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        <table className="w-full text-start text-slate-700 dark:text-slate-300 relative border-collapse">
          <thead className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest bg-slate-50/90 dark:bg-slate-800/90 sticky top-0 z-10 border-b border-slate-200/60 dark:border-slate-700/60 backdrop-blur-md">
            <tr>
              <th className="px-4 py-2.5 text-start font-bold">{isRtl ? "the name" : "Name"}</th>
              <th className="px-4 py-2.5 text-start font-bold">{isRtl ? "Value" : "Value"}</th>
              <th className="px-4 py-2.5 text-start font-bold">{isRtl ? "the condition" : "Status"}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100/50 dark:divide-slate-800/50">
            {rows.map((row: any, i) => (
              <tr
                key={row.id || i}
                className="group hover:bg-white dark:hover:bg-slate-800/50 transition-all duration-300 hover:shadow-[0_0_15px_rgba(0,0,0,0.03)] h-12 relative"
              >
                <td className="px-4 py-2 font-bold text-[13px] text-slate-800 dark:text-slate-200 max-w-[180px] sm:max-w-[240px] truncate group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                  {row.label || row.title}
                </td>
                <td
                  className="px-4 py-2 font-extrabold text-[13px] text-slate-700 dark:text-slate-300"
                  style={{ fontFamily: "Outfit, Inter, sans-serif" }}
                >
                  {row.primaryMeasure
                    ? formatDashboardValue(row.primaryMeasure.value, { compact: true })
                    : row.amount ?? row.reasonCode ?? "-"}
                </td>
                <td className="px-4 py-2">
                  <span
                    className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold border backdrop-blur-md uppercase tracking-wider ${getStatusBadge(
                      row.status,
                      row.severity
                    )}`}
                  >
                    {row.status || row.severity || "Active"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

